-- The CHAM-DRILL code key (Code keys -> Drilling -> CHAM-DRILL), from the ISCAR
-- e-catalog's CHAM-DRILL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.chamdrill', $ck${"title": "CHAM-DRILL code key – drilling heads, drill bodies and chamfering rings", "subtitle": "Exchangeable drilling heads (IDI) on DCM drill bodies (7.5 – 25.9 mm), DCT pre-thread drills and RING DCM chamfering rings", "example": "IDI 068-SG", "decoder": "cham-drill", "sections": [{"key": "i-family", "title": "Head / insert – family", "sample": "IDI", "rows": [{"code": "IDI", "meaning": "Drilling heads for DCM drill bodies"}, {"code": "XOGX", "meaning": "Inserts for the RING DCM chamfering rings"}]}, {"key": "i-dia", "title": "Head – drilling diameter", "sample": "068", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 068 = 6.8 mm)"}, {"code": "####", "meaning": "Drilling diameter x100"}]}, {"key": "i-suffix", "title": "Head – geometry", "sample": "SG", "rows": [{"code": "SG", "meaning": "General use"}, {"code": "SK", "meaning": "For cast iron"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "######", "meaning": "XOGX insert size (see the catalog)"}]}, {"key": "i-angle", "title": "Insert – chamfer angle", "rows": [{"code": "##", "meaning": "Chamfer angle in degrees (e.g. 45)"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "DT", "meaning": "General use chipformer"}]}, {"key": "t-family", "title": "Drill body / ring – family", "sample": "DCM", "rows": [{"code": "DCM", "meaning": "Drill body with exchangeable heads and internal coolant holes"}, {"code": "DCT", "meaning": "Drill body with exchangeable heads and chamfering inserts, for pre-thread holes (M8 – M24)"}, {"code": "RING DCM", "meaning": "Chamfering ring mounted on CHAM-DRILL drills, for drilling and chamfering in one operation"}]}, {"key": "t-dia", "title": "Drill body – head size", "rows": [{"code": "###", "meaning": "Smallest head diameter it carries x10 (e.g. 075 = 7.5 mm); DCT: pre-thread hole diameter"}]}, {"key": "t-length", "title": "Drill body – length", "rows": [{"code": "###", "meaning": "Usable length in mm (inferred)"}]}, {"key": "t-height", "title": "Drill body – shank diameter", "rows": [{"code": "#", "meaning": "Shank diameter in mm (e.g. 8)"}, {"code": "##", "meaning": "Shank diameter in mm (e.g. 12)"}]}, {"key": "t-shank", "title": "Drill body – shank type", "rows": [{"code": "A", "meaning": "One flat shank"}, {"code": "B", "meaning": "Flat shank without flange (for chamfering holders)"}]}, {"key": "t-depth", "title": "Drill body – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth ratio (e.g. 3D = 3xD)"}, {"code": "#.#D", "meaning": "Drilling depth ratio (3.5D = 3.5xD)"}]}, {"key": "t-thread", "title": "Drill body – thread", "rows": [{"code": "M##", "meaning": "DCT: the thread the pre-thread hole is for (e.g. M8)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
